INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yhW5vkcuZSq', 4, '{"title":"第20201720条・天元纪大论篇第六十六","description":"<p>14、鬼臾区曰：阴阳之气各有多少。故曰三阴三阳也。形有盛衰。谓五行之治。各有太过不及也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201720,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '14、鬼臾区曰：阴阳之气各有多少。故曰三阴三阳也。形有盛衰。谓五行之治。各有太过不及也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I9vAa8TxGuL', 4, '{"title":"第20201721条・天元纪大论篇第六十六","description":"<p>15、故其始也。有余而往。不足随之。不足而往。有余从之。知迎知随，气可与期。 应天为天符。承岁为岁直。三合为治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201721,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '15、故其始也。有余而往。不足随之。不足而往。有余从之。知迎知随，气可与期。 应天为天符。承岁为岁直。三合为治。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GekV4XjfD74', 4, '{"title":"第20201722条・天元纪大论篇第六十六","description":"<p>16、帝曰：上下相召奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201722,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '16、帝曰：上下相召奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9WAjc7A6uz3', 4, '{"title":"第20201723条・天元纪大论篇第六十六","description":"<p>17、鬼臾区曰：寒暑燥湿风火。天之阴阳也。三阴三阳上奉之。木火土金水火。地之阴阳也。生长化收藏下应之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201723,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '17、鬼臾区曰：寒暑燥湿风火。天之阴阳也。三阴三阳上奉之。木火土金水火。地之阴阳也。生长化收藏下应之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('18po2gCYub9', 4, '{"title":"第20201724条・天元纪大论篇第六十六","description":"<p>18、天以阳生阴长。地以阳杀阴藏。天有阴阳，地亦有阴阳。木火土金水火。地之阴阳也。生长化收藏。故阳中有阴。阴中有阳。所以欲知天地之阴阳者。应天之气。动而不息。故五岁而右迁。应地之气。静而守位。故六期而环会。动静相召。上下相临。阴阳相错。而变由生也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201724,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '18、天以阳生阴长。地以阳杀阴藏。天有阴阳，地亦有阴阳。木火土金水火。地之阴阳也。生长化收藏。故阳中有阴。阴中有阳。所以欲知天地之阴阳者。应天之气。动而不息。故五岁而右迁。应地之气。静而守位。故六期而环会。动静相召。上下相临。阴阳相错。而变由生也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9EwgTJUykXd', 4, '{"title":"第20201725条・天元纪大论篇第六十六","description":"<p>19、帝曰：上下周纪。其有数乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201725,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '19、帝曰：上下周纪。其有数乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sDPCFIiusjR', 4, '{"title":"第20201726条・天元纪大论篇第六十六","description":"<p>20、鬼臾区曰：天以六为节。地以五为制。周天气者。六期为一备。终地纪者。五岁为一周。君火以明。相火以位。五六相合而七百二十气。为一纪。凡三十岁。千四百四十气。凡六十岁。而为一周。不及太过。斯皆见矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201726,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '20、鬼臾区曰：天以六为节。地以五为制。周天气者。六期为一备。终地纪者。五岁为一周。君火以明。相火以位。五六相合而七百二十气。为一纪。凡三十岁。千四百四十气。凡六十岁。而为一周。不及太过。斯皆见矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cdgYV2qje3N', 4, '{"title":"第20201727条・天元纪大论篇第六十六","description":"<p>21、帝曰： 夫子之言，上终天气。下毕地纪。可谓悉矣。余愿闻而藏之。上以治民。下以治身。使百姓昭着。上下和亲。德泽下流。子孙无忧。传之后世。无有终时。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201727,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '21、帝曰： 夫子之言，上终天气。下毕地纪。可谓悉矣。余愿闻而藏之。上以治民。下以治身。使百姓昭着。上下和亲。德泽下流。子孙无忧。传之后世。无有终时。可得闻乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FrK0br568R1', 4, '{"title":"第20201728条・天元纪大论篇第六十六","description":"<p>22、鬼臾区曰：至数之机。迫迮以微。其来可见。其往可追。敬之者昌。慢之者亡。无道行私。必得夭殃。谨奉天道。请言真要。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201728,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '22、鬼臾区曰：至数之机。迫迮以微。其来可见。其往可追。敬之者昌。慢之者亡。无道行私。必得夭殃。谨奉天道。请言真要。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VQtJA0Iw6bA', 4, '{"title":"第20201729条・天元纪大论篇第六十六","description":"<p>23、帝曰：善言始者。必会于终。善言近者。必知其远。是则至数极而道不惑。所谓明矣。愿夫子推而次之。令有条理。简而不匮。久而不绝。易用难忘。为之纲纪。至数之要。愿尽闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201729,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '23、帝曰：善言始者。必会于终。善言近者。必知其远。是则至数极而道不惑。所谓明矣。愿夫子推而次之。令有条理。简而不匮。久而不绝。易用难忘。为之纲纪。至数之要。愿尽闻之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('htTv598vPRC', 4, '{"title":"第20201730条・天元纪大论篇第六十六","description":"<p>24、鬼臾区曰：昭乎哉问！明乎哉道！如鼓之应桴。响之应声也。臣闻之。甲己之岁。土运统之。乙庚之岁。金运统之。丙辛之岁。水运统之。丁壬之岁。木运统之。戊癸之岁。火运统之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201730,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '24、鬼臾区曰：昭乎哉问！明乎哉道！如鼓之应桴。响之应声也。臣闻之。甲己之岁。土运统之。乙庚之岁。金运统之。丙辛之岁。水运统之。丁壬之岁。木运统之。戊癸之岁。火运统之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h67gc1fdQz4', 4, '{"title":"第20201731条・天元纪大论篇第六十六","description":"<p>25、帝曰：其于三阴三阳。合之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201731,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '25、帝曰：其于三阴三阳。合之奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N9cv1CbkmS4', 4, '{"title":"第20201732条・天元纪大论篇第六十六","description":"<p>26、鬼臾区曰：子午之岁。上见少阴。丑未之岁。上见太阴。寅申之岁。上见少阳。卯酉之岁。上见阳明。辰戌之岁。上见太阳。巳亥之岁。上见厥阴。少阴所谓标也。厥阴所谓终也。厥阴之上。风气主之。少阴之上。热气主之。太阴之上。湿气主之。少阳之上。相火主之。阳明之上。燥气主之。太阳之上。寒气主之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201732,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '26、鬼臾区曰：子午之岁。上见少阴。丑未之岁。上见太阴。寅申之岁。上见少阳。卯酉之岁。上见阳明。辰戌之岁。上见太阳。巳亥之岁。上见厥阴。少阴所谓标也。厥阴所谓终也。厥阴之上。风气主之。少阴之上。热气主之。太阴之上。湿气主之。少阳之上。相火主之。阳明之上。燥气主之。太阳之上。寒气主之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('03fDkMq1Cs5', 4, '{"title":"第20201733条・天元纪大论篇第六十六","description":"<p>27、所谓本也。是谓六元。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201733,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '27、所谓本也。是谓六元。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i55nG87NcxQ', 4, '{"title":"第20201734条・天元纪大论篇第六十六","description":"<p>28、帝曰：光乎哉道！明乎哉论！请着之玉版。藏之金匮。署曰《天元纪》。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201734,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '28、帝曰：光乎哉道！明乎哉论！请着之玉版。藏之金匮。署曰《天元纪》。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F1BniMa46IW', 4, '{"title":"第20201735条・五运行大论篇第六十七","description":"<p>1、黄帝坐明堂。始正天纲。临观八极。考建五常。请天师而问之曰：论言天地之动静。神明为之纪。阴阳之升降。寒暑彰其兆。余闻五运之数于夫子。夫子之所言。正五气之各主岁尔。首甲定运。余因论之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201735,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '1、黄帝坐明堂。始正天纲。临观八极。考建五常。请天师而问之曰：论言天地之动静。神明为之纪。阴阳之升降。寒暑彰其兆。余闻五运之数于夫子。夫子之所言。正五气之各主岁尔。首甲定运。余因论之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x16G8YcjhWC', 4, '{"title":"第20201736条・五运行大论篇第六十七","description":"<p>2、鬼臾区曰：土主甲己。金主乙庚。水主丙辛。木主丁壬。火主戊癸。子午之上。少阴主之。丑未之上。太阴主之。寅申之上。少阳主之。卯酉之上。阳明主之。辰戌之上。太阳主之。巳亥之上。厥阴主之。不合阴阳。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201736,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2、鬼臾区曰：土主甲己。金主乙庚。水主丙辛。木主丁壬。火主戊癸。子午之上。少阴主之。丑未之上。太阴主之。寅申之上。少阳主之。卯酉之上。阳明主之。辰戌之上。太阳主之。巳亥之上。厥阴主之。不合阴阳。其故何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u8KkveloS0b', 4, '{"title":"第20201737条・五运行大论篇第六十七","description":"<p>3、岐伯曰：是明道也。此天地之阴阳也。夫数之可数者。人中之阴阳也。然所合。数之可得者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201737,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '3、岐伯曰：是明道也。此天地之阴阳也。夫数之可数者。人中之阴阳也。然所合。数之可得者也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8HO0QLjPNfJ', 4, '{"title":"第20201738条・五运行大论篇第六十七","description":"<p>4、夫阴阳者。数之可十。推之可百。数之可千。推之可万。天地阴阳者。不以数推以象之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201738,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '4、夫阴阳者。数之可十。推之可百。数之可千。推之可万。天地阴阳者。不以数推以象之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0yaVqGqUrHq', 4, '{"title":"第20201739条・五运行大论篇第六十七","description":"<p>5、帝曰：愿闻其所始也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201739,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '5、帝曰：愿闻其所始也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZgYEDDwD7Nl', 4, '{"title":"第20201740条・五运行大论篇第六十七","description":"<p>6、岐伯曰：昭乎哉问也！臣览《太始天元册》文。丹天之气经于牛女戊分。黅天之气经于心尾己分。苍天之气经于危室柳鬼。素天之气经于亢氐昴毕。玄天之气经于张翼娄胃。所谓戊己分者。奎壁角轸。则天地之门户也。夫候之所始。道之所生。不可不通也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201740,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '6、岐伯曰：昭乎哉问也！臣览《太始天元册》文。丹天之气经于牛女戊分。黅天之气经于心尾己分。苍天之气经于危室柳鬼。素天之气经于亢氐昴毕。玄天之气经于张翼娄胃。所谓戊己分者。奎壁角轸。则天地之门户也。夫候之所始。道之所生。不可不通也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oK5zTPJXjP1', 4, '{"title":"第20201741条・五运行大论篇第六十七","description":"<p>7、帝曰：善。论言天地者万物之上下。左右者阴阳之道路。未知其所谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201741,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '7、帝曰：善。论言天地者万物之上下。左右者阴阳之道路。未知其所谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lLPonJmos7P', 4, '{"title":"第20201742条・五运行大论篇第六十七","description":"<p>8、岐伯曰：所谓上下者。岁上下见阴阳之所在也。左右者。诸上见厥阴。左少阴右太阳。见少阴。左太阴右厥阴。见太阴。左少阳右少阴。见少阳。左阳明右太阴。见阳明。左太阳右少阳。见太阳。左厥阴|右阳明|。所谓面北而命其位。言其见也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201742,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '8、岐伯曰：所谓上下者。岁上下见阴阳之所在也。左右者。诸上见厥阴。左少阴右太阳。见少阴。左太阴右厥阴。见太阴。左少阳右少阴。见少阳。左阳明右太阴。见阳明。左太阳右少阳。见太阳。左厥阴|右阳明|。所谓面北而命其位。言其见也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vc4O44gHNgC', 4, '{"title":"第20201743条・五运行大论篇第六十七","description":"<p>9、帝曰：何谓下？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201743,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '9、帝曰：何谓下？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iwiOIjhkhCi', 4, '{"title":"第20201744条・五运行大论篇第六十七","description":"<p>10、岐伯曰：厥阴在上则少阳在下。左阳明右太阴。少阴在上则阳明在下。左太阳右少阳。太阴在上则太阳在下。左厥阴右阳明。少阳在上则厥阴在下。左少阴右太阳。阳明在上则少阴在下。左太阴右厥阴。太阳在上则太阴在下。左少阳右少阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201744,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '10、岐伯曰：厥阴在上则少阳在下。左阳明右太阴。少阴在上则阳明在下。左太阳右少阳。太阴在上则太阳在下。左厥阴右阳明。少阳在上则厥阴在下。左少阴右太阳。阳明在上则少阴在下。左太阴右厥阴。太阳在上则太阴在下。左少阳右少阴。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BTy8TBJ0v1D', 4, '{"title":"第20201745条・五运行大论篇第六十七","description":"<p>11、所谓面南而命其位。言其见也。上下相遘。寒暑相临。气相得则和。不相得则病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201745,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '11、所谓面南而命其位。言其见也。上下相遘。寒暑相临。气相得则和。不相得则病。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FYKaoIGAGX7', 4, '{"title":"第20201746条・五运行大论篇第六十七","description":"<p>12、帝曰：气相得而病者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201746,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '12、帝曰：气相得而病者何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3mhGv7rreCt', 4, '{"title":"第20201747条・五运行大论篇第六十七","description":"<p>13、岐伯曰：以下临上。不当位也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201747,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '13、岐伯曰：以下临上。不当位也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
