INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gxOCYcT6cao', 4, '{"title":"第20201749条・五运行大论篇第六十七","description":"<p>15、岐伯曰：上者右行。下者左行。左右周天。余而复会也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201749,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '15、岐伯曰：上者右行。下者左行。左右周天。余而复会也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o0I50zVtLOR', 4, '{"title":"第20201750条・五运行大论篇第六十七","description":"<p>16、帝曰：余闻鬼臾区曰：应地者静。今夫子乃言下者左行。不知其所谓也。愿闻何以生之乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201750,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '16、帝曰：余闻鬼臾区曰：应地者静。今夫子乃言下者左行。不知其所谓也。愿闻何以生之乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rk2HzuEITzJ', 4, '{"title":"第20201751条・五运行大论篇第六十七","description":"<p>17、岐伯曰：天地动静。五行迁复。虽鬼臾区其上候而已。犹不能遍明。夫变化之用。天垂象。地成形。七曜纬虚。五行丽地。地者。所以载生成之形类也。虚者。所以列应天之精气也。形精之动。犹根本之与枝叶也。仰观其象。虽远可知也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201751,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '17、岐伯曰：天地动静。五行迁复。虽鬼臾区其上候而已。犹不能遍明。夫变化之用。天垂象。地成形。七曜纬虚。五行丽地。地者。所以载生成之形类也。虚者。所以列应天之精气也。形精之动。犹根本之与枝叶也。仰观其象。虽远可知也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5UBa6SeXcwd', 4, '{"title":"第20201752条・五运行大论篇第六十七","description":"<p>18、帝曰：地之为下否乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201752,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '18、帝曰：地之为下否乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TWf27GZ1QaL', 4, '{"title":"第20201753条・五运行大论篇第六十七","description":"<p>19、岐伯曰：地为人之下。太虚之中者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201753,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '19、岐伯曰：地为人之下。太虚之中者也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YEjx2fJQVPi', 4, '{"title":"第20201754条・五运行大论篇第六十七","description":"<p>20、帝曰：冯乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201754,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '20、帝曰：冯乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8VYJOwhQIFR', 4, '{"title":"第20201755条・五运行大论篇第六十七","description":"<p>21、岐伯曰：大气举之也。燥以干之。暑以蒸之。风以动之。湿以润之。寒以坚之。火以温之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201755,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '21、岐伯曰：大气举之也。燥以干之。暑以蒸之。风以动之。湿以润之。寒以坚之。火以温之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tXbGCEtOCU5', 4, '{"title":"第20201756条・五运行大论篇第六十七","description":"<p>22、故风寒在下。燥热在上。湿气在中。火游行其间。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201756,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '22、故风寒在下。燥热在上。湿气在中。火游行其间。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
