INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZfF4YShtFQJ', 4, '{"title":"第20201760条・五运行大论篇第六十七","description":"<p>26、岐伯曰：天地之气。胜复之作。不形于诊也。《脉法》曰：天地之变。无以脉诊。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201760,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '26、岐伯曰：天地之气。胜复之作。不形于诊也。《脉法》曰：天地之变。无以脉诊。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
