INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mq7N33A0wd1', 4, '{"title":"第20201764条・五运行大论篇第六十七","description":"<p>30、岐伯曰：从其气则和。违其气则病。不当其位者病。迭移其位者病。失守其位者危。尺寸反者死。阴阳交者死。先立其年。以知其气。左右应见。然后乃可以言死生之逆顺。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201764,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '30、岐伯曰：从其气则和。违其气则病。不当其位者病。迭移其位者病。失守其位者危。尺寸反者死。阴阳交者死。先立其年。以知其气。左右应见。然后乃可以言死生之逆顺。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F6Bi5Qt2nJ4', 4, '{"title":"第20201765条・五运行大论篇第六十七","description":"<p>31、帝曰：寒暑燥湿风火。在人合之奈何？其于万物何以生化？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201765,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '31、帝曰：寒暑燥湿风火。在人合之奈何？其于万物何以生化？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TdyoFOrGv2Y', 4, '{"title":"第20201766条・五运行大论篇第六十七","description":"<p>32、岐伯曰：东方生风。风生木。木生酸。酸生肝。肝生筋。筋生心。其在天为玄。在人为道。在地为化。化生五味。道生智。玄生神。化生气。神在天为风。在地为木。在体为筋。在气为柔。在脏为肝。其性为暄。其德为和。其用为动。其色为苍。其化为荣。其虫毛。其政为散。其令宣发。其变摧拉。其眚为陨。其味为酸。其志为怒。怒伤肝。悲胜怒。风伤肝。燥胜风。酸伤筋。辛胜酸。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201766,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '32、岐伯曰：东方生风。风生木。木生酸。酸生肝。肝生筋。筋生心。其在天为玄。在人为道。在地为化。化生五味。道生智。玄生神。化生气。神在天为风。在地为木。在体为筋。在气为柔。在脏为肝。其性为暄。其德为和。其用为动。其色为苍。其化为荣。其虫毛。其政为散。其令宣发。其变摧拉。其眚为陨。其味为酸。其志为怒。怒伤肝。悲胜怒。风伤肝。燥胜风。酸伤筋。辛胜酸。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PLxPqrjngnP', 4, '{"title":"第20201767条・五运行大论篇第六十七","description":"<p>33、南方生热。热生火。火生苦。苦生心。心生血。血生脾。其在天为热。在地为火。在体为脉。在气为息。在脏为心。其性为暑。其德为显。其用为躁。其色为赤。其化为茂。其虫羽。其政为明。其令郁蒸。其变炎烁。其眚燔焫。其味为苦。其志为喜。喜伤心。恐胜喜。热伤气。寒胜热。苦伤气。咸胜苦。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201767,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '33、南方生热。热生火。火生苦。苦生心。心生血。血生脾。其在天为热。在地为火。在体为脉。在气为息。在脏为心。其性为暑。其德为显。其用为躁。其色为赤。其化为茂。其虫羽。其政为明。其令郁蒸。其变炎烁。其眚燔焫。其味为苦。其志为喜。喜伤心。恐胜喜。热伤气。寒胜热。苦伤气。咸胜苦。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VfhB1ntjfKv', 4, '{"title":"第20201768条・五运行大论篇第六十七","description":"<p>34、中央生湿。湿生土。土生甘。甘生脾。脾生肉。肉生肺。其在天为湿。在地为土。在体为肉。在气为充。在藏为脾。其性静兼。其德为濡。其用为化。其色为黄。其化为盈。其虫倮。其政为谧。其令云雨。其变动注。其眚淫溃。其味为甘。其志为思。思伤脾。怒胜思。湿伤肉。风胜湿。甘伤脾。酸胜甘。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201768,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '34、中央生湿。湿生土。土生甘。甘生脾。脾生肉。肉生肺。其在天为湿。在地为土。在体为肉。在气为充。在藏为脾。其性静兼。其德为濡。其用为化。其色为黄。其化为盈。其虫倮。其政为谧。其令云雨。其变动注。其眚淫溃。其味为甘。其志为思。思伤脾。怒胜思。湿伤肉。风胜湿。甘伤脾。酸胜甘。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wGFvEJJBAnH', 4, '{"title":"第20201769条・五运行大论篇第六十七","description":"<p>35、西方生燥。燥生金。金生辛。辛生肺。肺生皮毛。皮毛生肾。其在天为燥。在地为金。在体为皮毛。在气为成。在藏为肺。其性为凉。其德为清。其用为固。其色为白。其化为敛。其虫介。其政为劲。其令雾露。其变肃杀。其眚苍落。其味为辛。其志为忧。忧伤肺。喜胜忧。热伤皮毛。寒胜热。辛伤皮毛。苦胜辛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201769,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '35、西方生燥。燥生金。金生辛。辛生肺。肺生皮毛。皮毛生肾。其在天为燥。在地为金。在体为皮毛。在气为成。在藏为肺。其性为凉。其德为清。其用为固。其色为白。其化为敛。其虫介。其政为劲。其令雾露。其变肃杀。其眚苍落。其味为辛。其志为忧。忧伤肺。喜胜忧。热伤皮毛。寒胜热。辛伤皮毛。苦胜辛。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2X7PIRs7z6l', 4, '{"title":"第20201770条・五运行大论篇第六十七","description":"<p>36、北方生寒。寒生水。水生咸。咸生肾。肾生骨髓。髓生肝。其在天为寒。在地为水。在体为骨。在气为坚。在脏为肾。其性为凛。其德为寒。其用为藏。其色为黑。其化为肃。其虫鳞。其政为静。其令霰雪。其变凝冽。其眚冰雹。其味为咸。其志为恐。恐伤肾。思胜恐。寒伤血。燥胜寒。咸伤血。甘胜咸。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201770,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '36、北方生寒。寒生水。水生咸。咸生肾。肾生骨髓。髓生肝。其在天为寒。在地为水。在体为骨。在气为坚。在脏为肾。其性为凛。其德为寒。其用为藏。其色为黑。其化为肃。其虫鳞。其政为静。其令霰雪。其变凝冽。其眚冰雹。其味为咸。其志为恐。恐伤肾。思胜恐。寒伤血。燥胜寒。咸伤血。甘胜咸。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
