INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('56TiMMP81WC', 4, '{"title":"第20201775条・五运行大论篇第六十七","description":"<p>41、岐伯曰：气有余。则制己所胜而侮所不胜。其不及。则己所不胜侮而乘之。己所胜轻而侮之。侮反受邪。侮而受邪。寡于畏也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201775,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '41、岐伯曰：气有余。则制己所胜而侮所不胜。其不及。则己所不胜侮而乘之。己所胜轻而侮之。侮反受邪。侮而受邪。寡于畏也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('etvlKtri58K', 4, '{"title":"第20201776条・五运行大论篇第六十七","description":"<p>42、帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201776,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '42、帝曰：善。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'us00NXJpTro');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NVojXCDBa27', 4, '{"title":"第20201777条・六微旨大论篇第六十八","description":"<p>1、黄帝问曰：呜呼远哉！天之道也。如迎浮云。若视深渊。视深渊尚可测。迎浮云莫知其极。夫子数言谨奉天道。余闻而藏之。心私异之。不知其所谓也。愿夫子溢志尽言其事。令终不灭。久而不绝。天之道可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201777,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '1、黄帝问曰：呜呼远哉！天之道也。如迎浮云。若视深渊。视深渊尚可测。迎浮云莫知其极。夫子数言谨奉天道。余闻而藏之。心私异之。不知其所谓也。愿夫子溢志尽言其事。令终不灭。久而不绝。天之道可得闻乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fD4cpoA8tFN', 4, '{"title":"第20201778条・六微旨大论篇第六十八","description":"<p>2、岐伯稽首再拜对曰：明乎哉问。天之道也！此因天之序。盛衰之时也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201778,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2、岐伯稽首再拜对曰：明乎哉问。天之道也！此因天之序。盛衰之时也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OuhRscJJIsD', 4, '{"title":"第20201779条・六微旨大论篇第六十八","description":"<p>3、帝曰：愿闻天道六六之节盛衰何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201779,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '3、帝曰：愿闻天道六六之节盛衰何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JFH8zc8K4SB', 4, '{"title":"第20201780条・六微旨大论篇第六十八","description":"<p>4、岐伯曰：上下有位。左右有纪。故少阳之右。阳明治之。阳明之右。太阳治之。太阳之右。厥阴治之。厥阴之右。少阴治之。少阴之右。太阴治之。太阴之右。少阳治之。此所谓气之标。盖南面而待也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201780,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '4、岐伯曰：上下有位。左右有纪。故少阳之右。阳明治之。阳明之右。太阳治之。太阳之右。厥阴治之。厥阴之右。少阴治之。少阴之右。太阴治之。太阴之右。少阳治之。此所谓气之标。盖南面而待也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b9UdSKX1zvT', 4, '{"title":"第20201781条・六微旨大论篇第六十八","description":"<p>5、故曰：因天之序。盛衰之时。移光定位。正立而待之。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201781,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '5、故曰：因天之序。盛衰之时。移光定位。正立而待之。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mW2F11CPt8x', 4, '{"title":"第20201782条・六微旨大论篇第六十八","description":"<p>6、少阳之上。火气治之。中见厥阴。阳明之上。燥气之。中见太阴。太阳之上。寒气治之。中见少阴。厥阴之上。风气治之。中见少阳。少阴之上。热气治之。中见太阳。太阴之上。湿气治之。中见阳明。所谓本也。本之下。中之见也。见之下。气之标也。本标不同。气应异象。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201782,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '6、少阳之上。火气治之。中见厥阴。阳明之上。燥气之。中见太阴。太阳之上。寒气治之。中见少阴。厥阴之上。风气治之。中见少阳。少阴之上。热气治之。中见太阳。太阴之上。湿气治之。中见阳明。所谓本也。本之下。中之见也。见之下。气之标也。本标不同。气应异象。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iWDAdqnRwzY', 4, '{"title":"第20201783条・六微旨大论篇第六十八","description":"<p>7、帝曰：其有至而至。有至而不至。有至而太过。何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201783,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '7、帝曰：其有至而至。有至而不至。有至而太过。何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ebiywLYmnAQ', 4, '{"title":"第20201784条・六微旨大论篇第六十八","description":"<p>8、岐伯曰：至而至者和。至而不至。来气不及也。未至而至。来气有余也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201784,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '8、岐伯曰：至而至者和。至而不至。来气不及也。未至而至。来气有余也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
