INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hEg1BVRHi49', 4, '{"title":"第20201790条・六微旨大论篇第六十八","description":"<p>14、岐伯曰：显明之右。君火之位也。君火之右。退行一步。相火治之。复行一步。土气治之。复行一步。金气治之。复行一步。水气治之。复行一步。木气治之。复行一步。君火治之。相火之下。水气承之。水位之下。土气承之。土位之下。风气承之。风位之下。金气承之。金位之下。火气承之。君火之下。阴精承之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201790,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '14、岐伯曰：显明之右。君火之位也。君火之右。退行一步。相火治之。复行一步。土气治之。复行一步。金气治之。复行一步。水气治之。复行一步。木气治之。复行一步。君火治之。相火之下。水气承之。水位之下。土气承之。土位之下。风气承之。风位之下。金气承之。金位之下。火气承之。君火之下。阴精承之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
