INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xiwcsz32Z5g', 4, '{"title":"第20201843条・六微旨大论篇第六十八","description":"<p>67、岐伯曰：悉于哉问也！日行一周。天气始于一刻。日行再周。天气始于二十六刻。日行三周。天气始于五十一刻。日行四周。天气始于七十六刻。日行五周。天气复始于一刻。所谓一纪也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201843,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '67、岐伯曰：悉于哉问也！日行一周。天气始于一刻。日行再周。天气始于二十六刻。日行三周。天气始于五十一刻。日行四周。天气始于七十六刻。日行五周。天气复始于一刻。所谓一纪也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
