INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tp6KWP3twgo', 4, '{"title":"第20201859条・六微旨大论篇第六十八","description":"<p>83、岐伯曰：升已而降。降者谓天。降已而升。升者谓地。天气下降。气流于地。地气上升。气腾于天。故高下相召。升降相因。而变作矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201859,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '83、岐伯曰：升已而降。降者谓天。降已而升。升者谓地。天气下降。气流于地。地气上升。气腾于天。故高下相召。升降相因。而变作矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jSgNtWkfQ9K', 4, '{"title":"第20201860条・六微旨大论篇第六十八","description":"<p>84、帝曰：善。寒湿相遘。燥热相临。风火相值。其有间乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201860,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '84、帝曰：善。寒湿相遘。燥热相临。风火相值。其有间乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b1hMWGtWl1F', 4, '{"title":"第20201861条・六微旨大论篇第六十八","description":"<p>85、岐伯曰：气有胜复。胜复之作。有德有化。有用有变。变则邪气居之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201861,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '85、岐伯曰：气有胜复。胜复之作。有德有化。有用有变。变则邪气居之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zqkp2OPGgWs', 4, '{"title":"第20201862条・六微旨大论篇第六十八","description":"<p>86、帝曰：何谓邪乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201862,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '86、帝曰：何谓邪乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9505N1GNdgr', 4, '{"title":"第20201863条・六微旨大论篇第六十八","description":"<p>87、岐伯曰：夫物之生从于化。物之极由乎变。变化之相薄。成败之所由也。故气有往复。用有迟速。四者之有。而化而变。风之来也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201863,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '87、岐伯曰：夫物之生从于化。物之极由乎变。变化之相薄。成败之所由也。故气有往复。用有迟速。四者之有。而化而变。风之来也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9kX5pj0j20K', 4, '{"title":"第20201864条・六微旨大论篇第六十八","description":"<p>88、帝曰：迟速往复。风所由生。而化而变。故因盛衰之变耳。成败倚伏游乎中何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201864,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '88、帝曰：迟速往复。风所由生。而化而变。故因盛衰之变耳。成败倚伏游乎中何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z52YjXWzTbi', 4, '{"title":"第20201865条・六微旨大论篇第六十八","description":"<p>89、岐伯曰：成败倚伏生乎动。动而不已。则变作矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201865,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '89、岐伯曰：成败倚伏生乎动。动而不已。则变作矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
