INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Yqs59svJtX', 4, '{"title":"第20201867条・六微旨大论篇第六十八","description":"<p>91、岐伯曰：不生不化。静之期也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201867,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '91、岐伯曰：不生不化。静之期也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NV8UtXeXacr', 4, '{"title":"第20201868条・六微旨大论篇第六十八","description":"<p>92、帝曰：不生化乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201868,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '92、帝曰：不生化乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oyn6GHNxRRh', 4, '{"title":"第20201869条・六微旨大论篇第六十八","description":"<p>93、岐伯曰：出入废则神机化灭。升降息则气立孤危。故非出入。则无以生长壮老已。非升降。则无以生长化收藏。是以升降出入。无器不有。故器者生化之宇。器散则分之。生化息矣。故无不出入。无不升降。化有小大。期有近远。四者之有。而贵常守。反常则灾害至矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201869,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '93、岐伯曰：出入废则神机化灭。升降息则气立孤危。故非出入。则无以生长壮老已。非升降。则无以生长化收藏。是以升降出入。无器不有。故器者生化之宇。器散则分之。生化息矣。故无不出入。无不升降。化有小大。期有近远。四者之有。而贵常守。反常则灾害至矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2SE7vGPGUSx', 4, '{"title":"第20201870条・六微旨大论篇第六十八","description":"<p>94、故曰：无形无患。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201870,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '94、故曰：无形无患。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ebSYgnWmLW', 4, '{"title":"第20201871条・六微旨大论篇第六十八","description":"<p>95、帝曰：善。有不生不化乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201871,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '95、帝曰：善。有不生不化乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qT25X5G56Q0', 4, '{"title":"第20201872条・六微旨大论篇第六十八","description":"<p>96、岐伯曰：悉乎哉问也！与道协议。惟真人也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201872,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '96、岐伯曰：悉乎哉问也！与道协议。惟真人也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HXUNtjAK3AW', 4, '{"title":"第20201873条・六微旨大论篇第六十八","description":"<p>97、帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201873,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '97、帝曰：善。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QtmVqfHS9bS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vgBEmNCj4Mc', 4, '{"title":"第20201874条・气交变大论篇第六十九","description":"<p>1、黄帝问曰：五运更治。上应天期。阴阳往复。寒暑迎随。真邪相薄。内外分离。六经波荡。五气倾移。太过不及。专胜兼并。愿言其始。而有常名。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201874,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '1、黄帝问曰：五运更治。上应天期。阴阳往复。寒暑迎随。真邪相薄。内外分离。六经波荡。五气倾移。太过不及。专胜兼并。愿言其始。而有常名。可得闻乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S3HarCnSK5c', 4, '{"title":"第20201875条・气交变大论篇第六十九","description":"<p>2、岐伯稽首再拜对曰：昭乎哉问也！是明道也。此上帝所贵。先师传之。臣虽不敏。往闻其旨。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201875,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2、岐伯稽首再拜对曰：昭乎哉问也！是明道也。此上帝所贵。先师传之。臣虽不敏。往闻其旨。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iE8a16ubaiD', 4, '{"title":"第20201876条・气交变大论篇第六十九","description":"<p>3、帝曰：余闻得其人不教。是谓失道。传非其人。慢泄天宝。余诚菲德。未足以受至道。然而众子哀其不终。愿夫子保于无穷。流于无极。余司其事。则而行之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201876,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '3、帝曰：余闻得其人不教。是谓失道。传非其人。慢泄天宝。余诚菲德。未足以受至道。然而众子哀其不终。愿夫子保于无穷。流于无极。余司其事。则而行之奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bYmtJQi7XX9', 4, '{"title":"第20201877条・气交变大论篇第六十九","description":"<p>4、岐伯曰： 请遂言之也。《上经》曰：夫道者。上知天文。下知地理。中知人事。可以长久。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201877,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '4、岐伯曰： 请遂言之也。《上经》曰：夫道者。上知天文。下知地理。中知人事。可以长久。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DveOUr5FYiz', 4, '{"title":"第20201878条・气交变大论篇第六十九","description":"<p>5、帝曰：何谓也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201878,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '5、帝曰：何谓也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9MFwM0uFL37', 4, '{"title":"第20201879条・气交变大论篇第六十九","description":"<p>6、岐伯曰：本气位也。位天者。天文也。位地者。地理也。通于人气之变化者。人事也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201879,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '6、岐伯曰：本气位也。位天者。天文也。位地者。地理也。通于人气之变化者。人事也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0tBaf0wAL8Z', 4, '{"title":"第20201880条・气交变大论篇第六十九","description":"<p>7、故太过者先天。不及者后天。所谓治化而人应之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201880,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '7、故太过者先天。不及者后天。所谓治化而人应之也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v4izsiGaXpF', 4, '{"title":"第20201881条・气交变大论篇第六十九","description":"<p>8、帝曰：五运之化。太过何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201881,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '8、帝曰：五运之化。太过何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LiTNdOirYw8', 4, '{"title":"第20201882条・气交变大论篇第六十九","description":"<p>9、岐伯曰：岁木太过。风气流行。脾土受邪。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201882,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '9、岐伯曰：岁木太过。风气流行。脾土受邪。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tj7FaGTuBhk', 4, '{"title":"第20201883条・气交变大论篇第六十九","description":"<p>10、民病飧泄食减。体重烦冤。肠鸣腹支满。上应岁星。甚则忽忽善怒。眩冒巅疾。化气不政。生气独治。云物飞动。草木不宁。甚而摇落。反胁痛而吐甚。冲阳绝者死不治。上应太白星。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201883,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '10、民病飧泄食减。体重烦冤。肠鸣腹支满。上应岁星。甚则忽忽善怒。眩冒巅疾。化气不政。生气独治。云物飞动。草木不宁。甚而摇落。反胁痛而吐甚。冲阳绝者死不治。上应太白星。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lLaLgq91RKP', 4, '{"title":"第20201884条・气交变大论篇第六十九","description":"<p>11、岁火太过。炎暑流行。肺金受邪。民病疟。少气咳喘。血溢血泄注下。嗌燥耳聋。中热肩背热。上应荧惑星。甚则胸中痛。胁支满胁痛。膺背肩胛间痛。两臂内痛。身热骨痛而为浸淫。收气不行。长气独明。雨水霜寒。上应辰星。上临少阴少阳。火燔焫。水泉涸。物焦槁。病反谵妄狂越。咳喘息鸣。下甚血溢泄不已。太渊绝者死不治。上应荧惑星。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201884,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '11、岁火太过。炎暑流行。肺金受邪。民病疟。少气咳喘。血溢血泄注下。嗌燥耳聋。中热肩背热。上应荧惑星。甚则胸中痛。胁支满胁痛。膺背肩胛间痛。两臂内痛。身热骨痛而为浸淫。收气不行。长气独明。雨水霜寒。上应辰星。上临少阴少阳。火燔焫。水泉涸。物焦槁。病反谵妄狂越。咳喘息鸣。下甚血溢泄不已。太渊绝者死不治。上应荧惑星。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g3eHk7OHyl8', 4, '{"title":"第20201885条・气交变大论篇第六十九","description":"<p>12、岁土太过。雨湿流行。肾水受邪。民病腹痛。清厥意不乐。体重烦冤。上应镇星。甚则肌肉萎。足痿不收。行善瘛。脚下痛。饮发中满食减。四肢不举。变生得位。藏气伏。化气独治之。泉涌河衍。涸泽生鱼。风雨大至。土崩溃。鳞见于陆。病腹满溏泄肠鸣。反下甚而太溪绝者死不治。上应岁星。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201885,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '12、岁土太过。雨湿流行。肾水受邪。民病腹痛。清厥意不乐。体重烦冤。上应镇星。甚则肌肉萎。足痿不收。行善瘛。脚下痛。饮发中满食减。四肢不举。变生得位。藏气伏。化气独治之。泉涌河衍。涸泽生鱼。风雨大至。土崩溃。鳞见于陆。病腹满溏泄肠鸣。反下甚而太溪绝者死不治。上应岁星。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hsKXWMamNY9', 4, '{"title":"第20201886条・气交变大论篇第六十九","description":"<p>13、岁金太过。燥气流行。肝木受邪。民病两胁下少腹痛。目赤痛眦疡。耳无所闻。肃杀而甚。则体重烦冤。胸痛引背。两胁满且痛引少腹。上应太白星。甚则喘咳逆气。肩背痛。尻阴股膝髀腨䯒足皆病。上应荧惑星。收气峻。生气下。草木敛。苍干雕陨。病反暴痛。胠胁不可反侧。咳逆甚而血溢。太冲绝者死不治。上应太白星。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201886,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '13、岁金太过。燥气流行。肝木受邪。民病两胁下少腹痛。目赤痛眦疡。耳无所闻。肃杀而甚。则体重烦冤。胸痛引背。两胁满且痛引少腹。上应太白星。甚则喘咳逆气。肩背痛。尻阴股膝髀腨䯒足皆病。上应荧惑星。收气峻。生气下。草木敛。苍干雕陨。病反暴痛。胠胁不可反侧。咳逆甚而血溢。太冲绝者死不治。上应太白星。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('627CT4BnlIF', 4, '{"title":"第20201887条・气交变大论篇第六十九","description":"<p>14、岁水太过。寒气流行。邪害心火。民病身热烦心躁悸。阴厥上下中寒。谵妄心痛。寒气早至。上应辰星。甚则腹大胫肿。喘咳。寝汗出憎风。大雨至。埃雾朦郁。上应镇星。上临太阳。则雨冰雪。霜不时降。湿气变物。病反腹满肠鸣。溏泄食不化。渴而妄冒。神门绝者死不治。上应荧惑。辰星。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201887,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '14、岁水太过。寒气流行。邪害心火。民病身热烦心躁悸。阴厥上下中寒。谵妄心痛。寒气早至。上应辰星。甚则腹大胫肿。喘咳。寝汗出憎风。大雨至。埃雾朦郁。上应镇星。上临太阳。则雨冰雪。霜不时降。湿气变物。病反腹满肠鸣。溏泄食不化。渴而妄冒。神门绝者死不治。上应荧惑。辰星。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9FxPROEznkp', 4, '{"title":"第20201888条・气交变大论篇第六十九","description":"<p>15、帝曰：善。其不及何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201888,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '15、帝曰：善。其不及何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4UhygZfrP4q', 4, '{"title":"第20201889条・气交变大论篇第六十九","description":"<p>16、岐伯曰：悉乎哉问也！</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201889,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '16、岐伯曰：悉乎哉问也！', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P7DaL4oljSO', 4, '{"title":"第20201890条・气交变大论篇第六十九","description":"<p>17、岁木不及。燥乃大行。生气失应。草木晚荣。肃杀而甚。则刚木辟着。柔萎苍干。上应太白星。民病中清胠胁痛。少腹痛。肠鸣溏泄。凉雨时至。上应太白星。其谷苍。上临阳明。生气失政。草木再荣。化气乃急。上应太白。镇星。其主苍早。复则炎暑流火。湿性燥。柔脆草木焦槁。下体再生。华实齐化。病寒热疮疡。痱胗痈痤。上应荧惑。太白。其谷白坚。白露早降。收杀气行。寒雨害物。虫食甘黄。脾土受邪。赤气后化。心气晚治。上胜肺金。白气乃屈。其谷不成。咳而鼽。上应荧惑。太白星。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201890,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '17、岁木不及。燥乃大行。生气失应。草木晚荣。肃杀而甚。则刚木辟着。柔萎苍干。上应太白星。民病中清胠胁痛。少腹痛。肠鸣溏泄。凉雨时至。上应太白星。其谷苍。上临阳明。生气失政。草木再荣。化气乃急。上应太白。镇星。其主苍早。复则炎暑流火。湿性燥。柔脆草木焦槁。下体再生。华实齐化。病寒热疮疡。痱胗痈痤。上应荧惑。太白。其谷白坚。白露早降。收杀气行。寒雨害物。虫食甘黄。脾土受邪。赤气后化。心气晚治。上胜肺金。白气乃屈。其谷不成。咳而鼽。上应荧惑。太白星。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BM0r13hBp4m', 4, '{"title":"第20201891条・气交变大论篇第六十九","description":"<p>18、岁火不及。寒乃大行。长政不用。物荣而下。凝惨而甚。则阳气不化。乃折荣美。上应辰星。民病胸中痛。胁支满。两胁痛。膺背肩胛间及两臂内痛。郁冒朦昧。心痛暴喑。胸腹大。胁下与腰背相引而痛。甚则屈不能伸。髋髀如别。上应荧惑。辰星。其谷丹。复则埃郁。大雨且至。黑气乃辱。病鹜溏腹满。食饮不下。寒中肠鸣。泄注腹痛。暴挛痿痹。足不任身。上应镇星。辰星。玄谷不成。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201891,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '18、岁火不及。寒乃大行。长政不用。物荣而下。凝惨而甚。则阳气不化。乃折荣美。上应辰星。民病胸中痛。胁支满。两胁痛。膺背肩胛间及两臂内痛。郁冒朦昧。心痛暴喑。胸腹大。胁下与腰背相引而痛。甚则屈不能伸。髋髀如别。上应荧惑。辰星。其谷丹。复则埃郁。大雨且至。黑气乃辱。病鹜溏腹满。食饮不下。寒中肠鸣。泄注腹痛。暴挛痿痹。足不任身。上应镇星。辰星。玄谷不成。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OISfketL03d', 4, '{"title":"第20201892条・气交变大论篇第六十九","description":"<p>19、岁土不及。风乃大行。化气不令。草木茂荣。飘扬而甚。秀而不实。上应岁星。民病飧泄霍乱。体重腹痛。筋骨繇复。肌肉瞤酸。善怒。藏气举事。蛰虫早附。咸病寒中。上应岁星。镇星。其谷黅。复则收政严峻。名木苍雕。胸胁暴痛。下引少腹。善大息。虫食甘黄。气客于脾。黅谷乃减。民食少失味。苍谷乃损。上应太白。岁星。上临厥阴。流水不冰。蛰虫来见。藏气不用。白乃不复。上应岁星。民乃康。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201892,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '19、岁土不及。风乃大行。化气不令。草木茂荣。飘扬而甚。秀而不实。上应岁星。民病飧泄霍乱。体重腹痛。筋骨繇复。肌肉瞤酸。善怒。藏气举事。蛰虫早附。咸病寒中。上应岁星。镇星。其谷黅。复则收政严峻。名木苍雕。胸胁暴痛。下引少腹。善大息。虫食甘黄。气客于脾。黅谷乃减。民食少失味。苍谷乃损。上应太白。岁星。上临厥阴。流水不冰。蛰虫来见。藏气不用。白乃不复。上应岁星。民乃康。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('36hU7RxCW6X', 4, '{"title":"第20201893条・气交变大论篇第六十九","description":"<p>20、岁金不及。炎火乃行。生气乃用。长气专胜。庶物以茂。燥烁以行。上应荧惑星。民病肩背瞀重。鼽嚏血便注下。收气乃后。上应太白星。其谷坚芒。复则寒雨暴至。乃零冰雹霜雪杀物。阴厥且格阳反上行。头脑户痛。延及囟顶发热。上应辰星。丹谷不成。民病口疮。甚则心痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201893,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '20、岁金不及。炎火乃行。生气乃用。长气专胜。庶物以茂。燥烁以行。上应荧惑星。民病肩背瞀重。鼽嚏血便注下。收气乃后。上应太白星。其谷坚芒。复则寒雨暴至。乃零冰雹霜雪杀物。阴厥且格阳反上行。头脑户痛。延及囟顶发热。上应辰星。丹谷不成。民病口疮。甚则心痛。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O4QVxQRl0zO', 4, '{"title":"第20201894条・气交变大论篇第六十九","description":"<p>21、岁水不及。湿乃大行。长气反用。其化乃速。暑雨数至。上应镇星。民病腹满身重。濡泄寒疡流水。腰股痛发。腘腨股膝不便。烦冤足痿清厥。脚下痛。甚则跗肿。藏气不政。肾气不衡。上应镇星。辰星星。其谷黅。上临太阴。则大寒数举。蛰虫早藏。地积坚冰。阳光不治。民病寒疾于下。甚则腹满浮肿。上应镇星。其主黅谷 。复则大风暴发。草偃木零。生长不鲜。面色时变。筋骨并辟。肉 瞤瘛。目视䀮䀮。物疏璺。肌肉胗发。气并膈中。痛于心腹。黄气乃损。其谷不登。上应岁星。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201894,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '21、岁水不及。湿乃大行。长气反用。其化乃速。暑雨数至。上应镇星。民病腹满身重。濡泄寒疡流水。腰股痛发。腘腨股膝不便。烦冤足痿清厥。脚下痛。甚则跗肿。藏气不政。肾气不衡。上应镇星。辰星星。其谷黅。上临太阴。则大寒数举。蛰虫早藏。地积坚冰。阳光不治。民病寒疾于下。甚则腹满浮肿。上应镇星。其主黅谷 。复则大风暴发。草偃木零。生长不鲜。面色时变。筋骨并辟。肉 瞤瘛。目视䀮䀮。物疏璺。肌肉胗发。气并膈中。痛于心腹。黄气乃损。其谷不登。上应岁星。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2A5v0nt6GYE', 4, '{"title":"第20201895条・气交变大论篇第六十九","description":"<p>22、帝曰：善。愿闻其时也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201895,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '22、帝曰：善。愿闻其时也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hb28kkDNZu9', 4, '{"title":"第20201896条・气交变大论篇第六十九","description":"<p>23、岐伯曰：悉哉问也！</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201896,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '23、岐伯曰：悉哉问也！', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oAWj31CVX2e', 4, '{"title":"第20201897条・气交变大论篇第六十九","description":"<p>24、木不及。春有鸣条律畅之化。则秋有雾露清凉之政。春有惨凄残贼之胜。则夏有炎暑燔烁之复。其眚东。其藏肝。其病内舍膺胁。外在关节。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201897,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '24、木不及。春有鸣条律畅之化。则秋有雾露清凉之政。春有惨凄残贼之胜。则夏有炎暑燔烁之复。其眚东。其藏肝。其病内舍膺胁。外在关节。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vhHTAiyRl7u', 4, '{"title":"第20201898条・气交变大论篇第六十九","description":"<p>25、火不及。夏有炳明光显之化。则冬有严肃霜寒之政。夏有惨凄凝冽之胜。则不时有埃昏大雨之复。其眚南。其脏心。其病内舍膺胁。外在经络。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201898,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '25、火不及。夏有炳明光显之化。则冬有严肃霜寒之政。夏有惨凄凝冽之胜。则不时有埃昏大雨之复。其眚南。其脏心。其病内舍膺胁。外在经络。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KRxCM7gh5Cn', 4, '{"title":"第20201899条・气交变大论篇第六十九","description":"<p>26、土不及。四维有埃云润泽之化。则春有鸣条鼓拆之政。四维发振拉飘腾之变。则秋有肃杀霖霪之复。其眚四维。其脏脾。其病内舍心腹。外在肌肉四肢。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201899,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '26、土不及。四维有埃云润泽之化。则春有鸣条鼓拆之政。四维发振拉飘腾之变。则秋有肃杀霖霪之复。其眚四维。其脏脾。其病内舍心腹。外在肌肉四肢。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HdhKjsaNt2G', 4, '{"title":"第20201900条・气交变大论篇第六十九","description":"<p>27、金不及。夏有光显郁蒸之令。则冬有严凝整肃之应。夏有炎烁燔燎之变。则秋有冰雹霜雪之复。其眚西。其藏肺。其病内舍膺胁肩背。外在皮毛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201900,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '27、金不及。夏有光显郁蒸之令。则冬有严凝整肃之应。夏有炎烁燔燎之变。则秋有冰雹霜雪之复。其眚西。其藏肺。其病内舍膺胁肩背。外在皮毛。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l60Pz8I7w5n', 4, '{"title":"第20201901条・气交变大论篇第六十九","description":"<p>28、水不及，四维有湍润埃云之化。则不时有和风生发之应。四维发埃昏骤注之变。则不时有瓢荡振拉之复。其眚北。其藏肾。其病内舍腰脊骨髓。外在溪谷踹膝。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '28、水不及，四维有湍润埃云之化。则不时有和风生发之应。四维发埃昏骤注之变。则不时有瓢荡振拉之复。其眚北。其藏肾。其病内舍腰脊骨髓。外在溪谷踹膝。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7bRP35nUBh6', 4, '{"title":"第20201902条・气交变大论篇第六十九","description":"<p>29、夫五运之政。犹权衡也。高者抑之。下者举之。化者应之。变者复之。此生长化成收藏之理。气之常也。失常则天地四塞矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201902,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '29、夫五运之政。犹权衡也。高者抑之。下者举之。化者应之。变者复之。此生长化成收藏之理。气之常也。失常则天地四塞矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G4FwbiS8Aew', 4, '{"title":"第20201903条・气交变大论篇第六十九","description":"<p>30、故曰：天地之动静。神明为之纪。阴阳之往复。寒暑彰其兆。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201903,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '30、故曰：天地之动静。神明为之纪。阴阳之往复。寒暑彰其兆。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O2FX92HJwg1', 4, '{"title":"第20201904条・气交变大论篇第六十九","description":"<p>31、帝曰：夫子之言五气之变。四时之应。可谓悉矣。夫气之动乱。触遇而作。发无常会。卒然灾合。何以期之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201904,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '31、帝曰：夫子之言五气之变。四时之应。可谓悉矣。夫气之动乱。触遇而作。发无常会。卒然灾合。何以期之？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rp7MgCm6yx2', 4, '{"title":"第20201905条・气交变大论篇第六十九","description":"<p>32、岐伯曰：夫气之动变。固不常在。而德化政令灾变。不同其候也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201905,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '32、岐伯曰：夫气之动变。固不常在。而德化政令灾变。不同其候也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HVv7IWcF8EF', 4, '{"title":"第20201906条・气交变大论篇第六十九","description":"<p>33、帝曰：何谓也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201906,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '33、帝曰：何谓也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('09SvjFxjs2d', 4, '{"title":"第20201907条・气交变大论篇第六十九","description":"<p>34、岐伯曰：东方生风。风生木。其德敷和。其化生荣。其政舒启。其令风。其变振发。其灾散落。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201907,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '34、岐伯曰：东方生风。风生木。其德敷和。其化生荣。其政舒启。其令风。其变振发。其灾散落。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GQOhi2QfRyl', 4, '{"title":"第20201908条・气交变大论篇第六十九","description":"<p>35、南方生热。热生火。其德彰显。其化蕃。其政明曜。其令热。其变销烁。其灾燔 焫。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201908,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '35、南方生热。热生火。其德彰显。其化蕃。其政明曜。其令热。其变销烁。其灾燔 焫。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Pl07QQb0z4b', 4, '{"title":"第20201909条・气交变大论篇第六十九","description":"<p>36、中央生湿。湿生土。其德溽蒸。其化丰备。其政安静。其令湿。其变骤注。其灾霖溃。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201909,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '36、中央生湿。湿生土。其德溽蒸。其化丰备。其政安静。其令湿。其变骤注。其灾霖溃。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iVdcSTo07Dh', 4, '{"title":"第20201910条・气交变大论篇第六十九","description":"<p>37、西方生燥。燥生金。其德清洁。其化紧敛。其政劲切。其令燥。其变肃杀。其灾苍陨。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201910,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '37、西方生燥。燥生金。其德清洁。其化紧敛。其政劲切。其令燥。其变肃杀。其灾苍陨。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Nu7MoPonJU', 4, '{"title":"第20201911条・气交变大论篇第六十九","description":"<p>38、北方生寒。寒生水。其德凄沧。其化清谧。其政凝肃。其令寒。其变冽。其灾冰雪霜雹。是以察其动也。有德有化。有政有令。有变有灾。而物由之。而人应之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201911,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '38、北方生寒。寒生水。其德凄沧。其化清谧。其政凝肃。其令寒。其变冽。其灾冰雪霜雹。是以察其动也。有德有化。有政有令。有变有灾。而物由之。而人应之也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mU12zVP6i7B', 4, '{"title":"第20201912条・气交变大论篇第六十九","description":"<p>39、帝曰：夫子之言岁候。其不及太过。而上应五星。今夫德化政令。灾眚变易。非常而有也。卒然而动。其亦为之变乎。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201912,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '39、帝曰：夫子之言岁候。其不及太过。而上应五星。今夫德化政令。灾眚变易。非常而有也。卒然而动。其亦为之变乎。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JqBAjNMNJ2k', 4, '{"title":"第20201913条・气交变大论篇第六十九","description":"<p>40、岐伯曰：承天而行之。故无妄动。无不应也。卒然而动者。气之交变也。其不应焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201913,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '40、岐伯曰：承天而行之。故无妄动。无不应也。卒然而动者。气之交变也。其不应焉。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x6Mk3pYXzPX', 4, '{"title":"第20201914条・气交变大论篇第六十九","description":"<p>41、故曰： 应常不应卒。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201914,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '41、故曰： 应常不应卒。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cTBruhBCtXv', 4, '{"title":"第20201915条・气交变大论篇第六十九","description":"<p>42、帝曰：其应奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201915,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '42、帝曰：其应奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cccUBKql2Z2', 4, '{"title":"第20201916条・气交变大论篇第六十九","description":"<p>43、岐伯曰：各从其气化也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201916,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '43、岐伯曰：各从其气化也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LYoZWQGJSlW', 4, '{"title":"第20201917条・气交变大论篇第六十九","description":"<p>44、帝曰：其行之徐疾逆顺何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201917,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '44、帝曰：其行之徐疾逆顺何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G5ibMuld1OS', 4, '{"title":"第20201918条・气交变大论篇第六十九","description":"<p>45、岐伯曰：以道留久。逆守而小。是谓省下以道而去。去而速来。曲而过之。是谓省遗过也。久留而环。或离或附。是谓议灾与其德也。应近则小。应远则大。芒而大倍常之一。其化甚。大常之二。其眚即发也。小常之一。其化减。小常之二。是谓临视。省下之过与其德也。德者福之。过者伐之。是以象之见也。高而远则小。下而近则大。故大则喜怒迩。小则祸福远。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201918,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '45、岐伯曰：以道留久。逆守而小。是谓省下以道而去。去而速来。曲而过之。是谓省遗过也。久留而环。或离或附。是谓议灾与其德也。应近则小。应远则大。芒而大倍常之一。其化甚。大常之二。其眚即发也。小常之一。其化减。小常之二。是谓临视。省下之过与其德也。德者福之。过者伐之。是以象之见也。高而远则小。下而近则大。故大则喜怒迩。小则祸福远。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tRpJn5sJiRJ', 4, '{"title":"第20201919条・气交变大论篇第六十九","description":"<p>46、岁运太过。则运星北越。运气相得。则各行以道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201919,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '46、岁运太过。则运星北越。运气相得。则各行以道。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5NA4VywPw6E', 4, '{"title":"第20201920条・气交变大论篇第六十九","description":"<p>47、故岁运太过。畏星失色而兼其母。不及。则色兼其所不胜。肖者瞿瞿。莫知其妙。闵闵之当。孰者为良。妄行无征。示畏侯王。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201920,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '47、故岁运太过。畏星失色而兼其母。不及。则色兼其所不胜。肖者瞿瞿。莫知其妙。闵闵之当。孰者为良。妄行无征。示畏侯王。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aPq20a57ozA', 4, '{"title":"第20201921条・气交变大论篇第六十九","description":"<p>48、帝曰：其灾应何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201921,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '48、帝曰：其灾应何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ntdPWzgfhVk', 4, '{"title":"第20201922条・气交变大论篇第六十九","description":"<p>49、岐伯曰： 亦各从其化也。故时至有盛衰。凌犯有逆顺。留守有多少。形见有善恶。宿属有胜负。征应有吉凶矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201922,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '49、岐伯曰： 亦各从其化也。故时至有盛衰。凌犯有逆顺。留守有多少。形见有善恶。宿属有胜负。征应有吉凶矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
