INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yHWgnWZ3tde', 4, '{"title":"第20201926条・气交变大论篇第六十九","description":"<p>53、岐伯曰：象见高下。其应一也。故人亦应之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201926,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '53、岐伯曰：象见高下。其应一也。故人亦应之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lXeHBpa5bmE', 4, '{"title":"第20201927条・气交变大论篇第六十九","description":"<p>54、帝曰：善。其德化政令之动静损益皆何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201927,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '54、帝曰：善。其德化政令之动静损益皆何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pfuq9tWRBGh', 4, '{"title":"第20201928条・气交变大论篇第六十九","description":"<p>55、岐伯曰：夫德化政令灾变。不能相加也。胜复盛衰。不能相多也。往来小大。不能相过也。用之升降。不能相无也。各从其动而复之耳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201928,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '55、岐伯曰：夫德化政令灾变。不能相加也。胜复盛衰。不能相多也。往来小大。不能相过也。用之升降。不能相无也。各从其动而复之耳。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xDO4haKO30v', 4, '{"title":"第20201929条・气交变大论篇第六十九","description":"<p>56、帝曰：其病生何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201929,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '56、帝曰：其病生何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MBX6W0fU6xX', 4, '{"title":"第20201930条・气交变大论篇第六十九","description":"<p>57、岐伯曰： 德化者气之祥。政令者气之章。变易者复之纪。灾眚者伤之始。气相胜者和。不相胜者病。重感于邪则甚也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201930,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '57、岐伯曰： 德化者气之祥。政令者气之章。变易者复之纪。灾眚者伤之始。气相胜者和。不相胜者病。重感于邪则甚也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1wZC2p0qPUp', 4, '{"title":"第20201931条・气交变大论篇第六十九","description":"<p>58、帝曰：善。所谓精光之论。大圣之业。宣明大道。通于无穷。究于无极也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201931,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '58、帝曰：善。所谓精光之论。大圣之业。宣明大道。通于无穷。究于无极也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uyJfC8UCELV', 4, '{"title":"第20201932条・气交变大论篇第六十九","description":"<p>59、余闻之。善言天者。必应于人。善言古者。必验于今。善言气者。必彰于物。善言应者。同天地之化。善言化言变者。通神明之理。非夫子孰能言至道欤！乃择良兆而藏之灵室。每旦读之。命曰《气交变》。非斋戒不敢发。慎传也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201932,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '59、余闻之。善言天者。必应于人。善言古者。必验于今。善言气者。必彰于物。善言应者。同天地之化。善言化言变者。通神明之理。非夫子孰能言至道欤！乃择良兆而藏之灵室。每旦读之。命曰《气交变》。非斋戒不敢发。慎传也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oUTK0pI0jcT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TK7Ym3RuIgf', 4, '{"title":"第20201933条・五常政大论篇第七十","description":"<p>1、黄帝问曰：太虚寥廓。五运回薄。衰盛不同。损益相从。愿闻平气何如而名？何如而纪也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201933,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '1、黄帝问曰：太虚寥廓。五运回薄。衰盛不同。损益相从。愿闻平气何如而名？何如而纪也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZlHie4098oC', 4, '{"title":"第20201934条・五常政大论篇第七十","description":"<p>2、岐伯对曰： 昭乎哉问也！木曰敷和。火曰升明。土曰备化。金曰审平。水曰静顺。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201934,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2、岐伯对曰： 昭乎哉问也！木曰敷和。火曰升明。土曰备化。金曰审平。水曰静顺。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oSbbwwvcyJQ', 4, '{"title":"第20201935条・五常政大论篇第七十","description":"<p>3、帝曰：其不及奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201935,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '3、帝曰：其不及奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
