INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3Cz2Gl3m9lP', 4, '{"title":"第20201941条・五常政大论篇第七十","description":"<p>9、敷和之纪。木德周行。阳舒阴布。五化宣平。其气端。其性随。其用曲直。其化生荣。其类草木。其政发散。其候温和。其令风。其藏肝。肝其畏清。其主目。其谷麻。其果李。其实核。其应春。其虫毛。其畜犬。其色苍。其养筋。其病里急支满。其味酸。其音角。其物中坚。其数八。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201941,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '9、敷和之纪。木德周行。阳舒阴布。五化宣平。其气端。其性随。其用曲直。其化生荣。其类草木。其政发散。其候温和。其令风。其藏肝。肝其畏清。其主目。其谷麻。其果李。其实核。其应春。其虫毛。其畜犬。其色苍。其养筋。其病里急支满。其味酸。其音角。其物中坚。其数八。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cHKOxl6o3td', 4, '{"title":"第20201942条・五常政大论篇第七十","description":"<p>10、升明之纪。正阳而治。德施周普。五化均衡。其气高。其性速、其用燔灼。其化蕃茂。其类火。其政明曜。其候炎暑。其令热。其藏心。心其畏寒。其主舌。其谷麦。其果杏。其实络。其应夏。其虫羽。其畜马。其色赤。其养血。其病螈。其味苦。其音征。其物脉。其数七。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201942,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '10、升明之纪。正阳而治。德施周普。五化均衡。其气高。其性速、其用燔灼。其化蕃茂。其类火。其政明曜。其候炎暑。其令热。其藏心。心其畏寒。其主舌。其谷麦。其果杏。其实络。其应夏。其虫羽。其畜马。其色赤。其养血。其病螈。其味苦。其音征。其物脉。其数七。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dqr240w9ENm', 4, '{"title":"第20201943条・五常政大论篇第七十","description":"<p>11、备化之纪，气协天休，德流四政，五化齐修，其气平，其性顺，其用高下，其化丰满，其类土，其政 安静，其候溽蒸，其令湿，其脏脾，脾其畏风，其主口，其谷稷，其果枣，其实肉，其应长夏。其虫 。其畜牛。其色黄。其养肉。其病痞。其味甘。其音宫。其物肤。其数五。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201943,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '11、备化之纪，气协天休，德流四政，五化齐修，其气平，其性顺，其用高下，其化丰满，其类土，其政 安静，其候溽蒸，其令湿，其脏脾，脾其畏风，其主口，其谷稷，其果枣，其实肉，其应长夏。其虫 。其畜牛。其色黄。其养肉。其病痞。其味甘。其音宫。其物肤。其数五。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nXF49UUM0cz', 4, '{"title":"第20201944条・五常政大论篇第七十","description":"<p>12、审平之纪。收而不争。杀而无犯。五化宣明。其气洁。其性刚。其用散落。其化坚敛。其类金。其政劲肃。其候清切。其令燥。其脏肺。肺其畏热。其主鼻。其谷稻。其果桃。其实壳。其应秋。其虫介。其畜鸡。其色白。其养皮毛。其病咳。其味辛。其音商。其物外坚。其数九。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201944,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '12、审平之纪。收而不争。杀而无犯。五化宣明。其气洁。其性刚。其用散落。其化坚敛。其类金。其政劲肃。其候清切。其令燥。其脏肺。肺其畏热。其主鼻。其谷稻。其果桃。其实壳。其应秋。其虫介。其畜鸡。其色白。其养皮毛。其病咳。其味辛。其音商。其物外坚。其数九。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ua402cBwX6o', 4, '{"title":"第20201945条・五常政大论篇第七十","description":"<p>13、静顺之纪。藏而勿害。治而善下。五化咸整。其气明。其性下。其用沃衍。其化凝坚。其类 水。其政流演。其候凝肃。其令寒。其脏肾。肾其畏湿。其主二阴。其谷豆。其果栗。其实濡。其应冬。虫鳞。其畜彘。其色黑。其养骨髓。其病厥。其味咸。其音羽。其物濡。其数六。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201945,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '13、静顺之纪。藏而勿害。治而善下。五化咸整。其气明。其性下。其用沃衍。其化凝坚。其类 水。其政流演。其候凝肃。其令寒。其脏肾。肾其畏湿。其主二阴。其谷豆。其果栗。其实濡。其应冬。虫鳞。其畜彘。其色黑。其养骨髓。其病厥。其味咸。其音羽。其物濡。其数六。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K8qUOkpuyyf', 4, '{"title":"第20201946条・五常政大论篇第七十","description":"<p>14、故生而勿杀。长而勿罚。化而勿制。收而勿害。藏而勿抑。是谓平气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201946,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '14、故生而勿杀。长而勿罚。化而勿制。收而勿害。藏而勿抑。是谓平气。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VDrwUeMppAO', 4, '{"title":"第20201947条・五常政大论篇第七十","description":"<p>15、委和之纪。是谓胜生。生气不政。化气乃扬。长气自平。收令乃早。凉雨时降。风云并兴。草木晚荣。苍干雕落。物秀而实。肤肉内充。其气敛。其用聚。其动緛戾拘缓。其发惊骇。其藏肝。其果枣李。其实核壳。其谷稷稻。其味酸辛。其色白苍。其畜犬鸡。其虫毛介。其主雾露凄沧。其声角商。其病摇动注恐。从金化也。少角与判商同。上角与正角同。上商与正商同。其病肢废。痈肿疮疡。其甘虫。邪伤肝也。上宫与正宫同。萧飋杀则炎赫沸腾。眚于三。所谓复也。其主飞蠹蛆雉。乃为雷霆。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201947,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '15、委和之纪。是谓胜生。生气不政。化气乃扬。长气自平。收令乃早。凉雨时降。风云并兴。草木晚荣。苍干雕落。物秀而实。肤肉内充。其气敛。其用聚。其动緛戾拘缓。其发惊骇。其藏肝。其果枣李。其实核壳。其谷稷稻。其味酸辛。其色白苍。其畜犬鸡。其虫毛介。其主雾露凄沧。其声角商。其病摇动注恐。从金化也。少角与判商同。上角与正角同。上商与正商同。其病肢废。痈肿疮疡。其甘虫。邪伤肝也。上宫与正宫同。萧飋杀则炎赫沸腾。眚于三。所谓复也。其主飞蠹蛆雉。乃为雷霆。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QZ7ld1GKlEy', 4, '{"title":"第20201948条・五常政大论篇第七十","description":"<p>16、伏明之纪。是谓胜长。长气不宣。藏气反布。收气自政。化令乃衡。寒清数举。暑令乃薄。承化物生。生而不长。成实而稚。遇化已老。阳气屈伏。蛰虫早藏。其气郁。其用暴。其动彰伏变易。其发痛。其藏心。其果栗桃。其实络濡。其谷豆稻。其味苦咸。其色玄丹。其畜马彘。其虫羽鳞。其主冰雪霜寒。其声征羽。其病昏惑悲忘。从水化也。少征与少羽同。上商与正商同。邪伤心也。凝惨凛冽则豪雨霖霪。眚于九。其主骤注雷霆震惊。沉阴淫雨。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201948,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '16、伏明之纪。是谓胜长。长气不宣。藏气反布。收气自政。化令乃衡。寒清数举。暑令乃薄。承化物生。生而不长。成实而稚。遇化已老。阳气屈伏。蛰虫早藏。其气郁。其用暴。其动彰伏变易。其发痛。其藏心。其果栗桃。其实络濡。其谷豆稻。其味苦咸。其色玄丹。其畜马彘。其虫羽鳞。其主冰雪霜寒。其声征羽。其病昏惑悲忘。从水化也。少征与少羽同。上商与正商同。邪伤心也。凝惨凛冽则豪雨霖霪。眚于九。其主骤注雷霆震惊。沉阴淫雨。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LsECGykETSf', 4, '{"title":"第20201949条・五常政大论篇第七十","description":"<p>17、卑监之纪。是谓减化。化气不令。生政独彰。长气整。雨乃愆。收气平。风寒并兴。草木荣美。秀而不实。成而秕也。其气散。其用静定。其动疡涌分溃痈肿。其发濡滞。其藏脾。其果李栗。其实濡核。其谷豆麻。其味酸甘。其色苍黄。其畜牛犬。其虫毛。其主飘怒振发。其声宫角。其病留满痞塞。从木化也。少宫与少角同。上宫与正宫同。上角与正角同。其病飧泄。邪伤脾也。振拉飘扬则苍干散落。其眚四维。其主败折虎狼。清气乃用。生政乃辱。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201949,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '17、卑监之纪。是谓减化。化气不令。生政独彰。长气整。雨乃愆。收气平。风寒并兴。草木荣美。秀而不实。成而秕也。其气散。其用静定。其动疡涌分溃痈肿。其发濡滞。其藏脾。其果李栗。其实濡核。其谷豆麻。其味酸甘。其色苍黄。其畜牛犬。其虫毛。其主飘怒振发。其声宫角。其病留满痞塞。从木化也。少宫与少角同。上宫与正宫同。上角与正角同。其病飧泄。邪伤脾也。振拉飘扬则苍干散落。其眚四维。其主败折虎狼。清气乃用。生政乃辱。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ny8nru720v9', 4, '{"title":"第20201950条・五常政大论篇第七十","description":"<p>18、从革之纪。是谓折收。收气乃后。生气乃扬。长化合德。火政乃宣。庶类以蕃。其气扬。其用躁切。其动铿禁瞀厥。其发咳喘。其脏肺。其果李杏。其实壳络。其谷麻麦。其味苦辛。其色白丹。其畜鸡羊。其虫介羽。其主明曜炎烁。其声商征。其病嚏咳鼽衄。从火化也。少商与少征同。上商与正商同。上角与正角同。邪伤肺也。炎光赫烈则冰雪霜雹。眚于七。其主鳞伏彘鼠。岁气早至。乃生大寒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201950,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '18、从革之纪。是谓折收。收气乃后。生气乃扬。长化合德。火政乃宣。庶类以蕃。其气扬。其用躁切。其动铿禁瞀厥。其发咳喘。其脏肺。其果李杏。其实壳络。其谷麻麦。其味苦辛。其色白丹。其畜鸡羊。其虫介羽。其主明曜炎烁。其声商征。其病嚏咳鼽衄。从火化也。少商与少征同。上商与正商同。上角与正角同。邪伤肺也。炎光赫烈则冰雪霜雹。眚于七。其主鳞伏彘鼠。岁气早至。乃生大寒。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yXDcFjlhPJZ', 4, '{"title":"第20201951条・五常政大论篇第七十","description":"<p>19、涸流之纪。是谓反阳。藏令不举。化气乃昌。长气宣布。蛰虫不藏。土润水泉减。草木条茂。荣秀满盛。其气滞。其用渗泄。其动坚止。其发燥槁。其藏肾。其果枣杏。其实濡肉。其谷黍稷。其味甘咸。其色玄。其畜彘牛。其虫鳞。其主埃郁昏翳。其声羽宫。其病痿厥坚下。从土化也。少羽与少宫同。上宫与正宫同。其病癃。邪伤肾也。埃昏骤雨则振拉摧拔。眚于一。其主毛显狐貉。变化不藏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201951,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '19、涸流之纪。是谓反阳。藏令不举。化气乃昌。长气宣布。蛰虫不藏。土润水泉减。草木条茂。荣秀满盛。其气滞。其用渗泄。其动坚止。其发燥槁。其藏肾。其果枣杏。其实濡肉。其谷黍稷。其味甘咸。其色玄。其畜彘牛。其虫鳞。其主埃郁昏翳。其声羽宫。其病痿厥坚下。从土化也。少羽与少宫同。上宫与正宫同。其病癃。邪伤肾也。埃昏骤雨则振拉摧拔。眚于一。其主毛显狐貉。变化不藏。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9eGkNLMqDfA', 4, '{"title":"第20201952条・五常政大论篇第七十","description":"<p>20、故乘危而行。不速而至。炎威无德。灾反及之。微者复微。甚者复甚。气之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201952,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '20、故乘危而行。不速而至。炎威无德。灾反及之。微者复微。甚者复甚。气之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vnKUkUtZ8nH', 4, '{"title":"第20201953条・五常政大论篇第七十","description":"<p>21、发生之纪。是谓启陈。土疏泄。苍气达。阳和布化。阴气乃随。生气淳化。万物以荣。其化生。其气美。其政散。其令条舒。其动掉眩巅疾。其德鸣靡启坼。其变振拉摧拔。其谷麻稻。其畜鸡犬。其果李桃。其色青黄白。其味酸甘辛。其象春。其经足厥阴少阳。其藏肝脾。其虫毛介。其物中坚外坚。其病怒。太角与上商同。上征则其气逆。其病吐利。不务其德则收气复。秋气劲切。甚则肃杀。清气大至。草木雕零。邪乃伤肝。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201953,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '21、发生之纪。是谓启陈。土疏泄。苍气达。阳和布化。阴气乃随。生气淳化。万物以荣。其化生。其气美。其政散。其令条舒。其动掉眩巅疾。其德鸣靡启坼。其变振拉摧拔。其谷麻稻。其畜鸡犬。其果李桃。其色青黄白。其味酸甘辛。其象春。其经足厥阴少阳。其藏肝脾。其虫毛介。其物中坚外坚。其病怒。太角与上商同。上征则其气逆。其病吐利。不务其德则收气复。秋气劲切。甚则肃杀。清气大至。草木雕零。邪乃伤肝。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BzVz8G0y9MG', 4, '{"title":"第20201954条・五常政大论篇第七十","description":"<p>22、赫曦之纪。是谓蕃茂。阴气内化。阳气外荣。炎暑施化。物得以昌。其化长。其气高。其政动。其令鸣显。其动炎灼妄扰。其德暄暑郁蒸。其变炎烈沸腾。其谷麦豆。其畜羊彘。其果杏栗。其色赤白玄。其味苦辛咸。其象夏。其经手少阴太阳。手厥阴少阳。其藏心肺。其虫羽鳞。其物脉濡。其病笑疟疮疡血流。狂妄目赤。上羽与正征同。其收齐。其病痓。上征而收气后也。暴烈其政。脏气乃复。时见凝惨。甚则雨水霜雹切寒。邪伤心也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201954,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '22、赫曦之纪。是谓蕃茂。阴气内化。阳气外荣。炎暑施化。物得以昌。其化长。其气高。其政动。其令鸣显。其动炎灼妄扰。其德暄暑郁蒸。其变炎烈沸腾。其谷麦豆。其畜羊彘。其果杏栗。其色赤白玄。其味苦辛咸。其象夏。其经手少阴太阳。手厥阴少阳。其藏心肺。其虫羽鳞。其物脉濡。其病笑疟疮疡血流。狂妄目赤。上羽与正征同。其收齐。其病痓。上征而收气后也。暴烈其政。脏气乃复。时见凝惨。甚则雨水霜雹切寒。邪伤心也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m41memMgx1H', 4, '{"title":"第20201955条・五常政大论篇第七十","description":"<p>23、敦阜之纪。是谓广化。浓德清静。顺长以盈。至阴内实。物化充成。烟埃朦郁。见于浓土。大雨时行。湿气乃用。燥政乃辟。其化圆。其气丰。其政静。其令周备。其动濡积并稸。其德柔润重淖。其变震惊飘骤崩溃。其谷稷麻。其畜牛犬。其果枣李。其色玄苍。其味甘咸酸。其象长夏。其经足太阴阳明。其藏脾肾。其虫毛。其物肌核。其病腹满四肢不举。大风迅至。邪伤脾也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201955,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '23、敦阜之纪。是谓广化。浓德清静。顺长以盈。至阴内实。物化充成。烟埃朦郁。见于浓土。大雨时行。湿气乃用。燥政乃辟。其化圆。其气丰。其政静。其令周备。其动濡积并稸。其德柔润重淖。其变震惊飘骤崩溃。其谷稷麻。其畜牛犬。其果枣李。其色玄苍。其味甘咸酸。其象长夏。其经足太阴阳明。其藏脾肾。其虫毛。其物肌核。其病腹满四肢不举。大风迅至。邪伤脾也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OLW4LykDMTb', 4, '{"title":"第20201956条・五常政大论篇第七十","description":"<p>24、坚成之纪。是谓收引。天气洁。地气明。阳气随。阴治化。燥行其政。物以司成。收气繁布。化洽不终。其化成。其气削。其政肃。其令锐切。其动暴折疡疰。其德雾露萧飋。其肃杀雕零。其谷稻黍。其畜鸡马。其果桃杏。其色白青丹。其味辛酸苦。其象秋。其经手太阴阳明。其藏肺肝。其虫介羽。其物壳络。其病喘喝胸凭仰息。上徵与正商同。其生齐。其病咳。政暴变则名木不荣。柔脆焦首。长气斯救。大火流。炎烁且至。蔓将槁。邪伤肺也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201956,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '24、坚成之纪。是谓收引。天气洁。地气明。阳气随。阴治化。燥行其政。物以司成。收气繁布。化洽不终。其化成。其气削。其政肃。其令锐切。其动暴折疡疰。其德雾露萧飋。其肃杀雕零。其谷稻黍。其畜鸡马。其果桃杏。其色白青丹。其味辛酸苦。其象秋。其经手太阴阳明。其藏肺肝。其虫介羽。其物壳络。其病喘喝胸凭仰息。上徵与正商同。其生齐。其病咳。政暴变则名木不荣。柔脆焦首。长气斯救。大火流。炎烁且至。蔓将槁。邪伤肺也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kDP6jlb3obS', 4, '{"title":"第20201957条・五常政大论篇第七十","description":"<p>25、流衍之纪。是谓封藏。寒司物化。天地严凝。藏政以布。长令不扬。其化凛。其气坚。其政谧。其令流注。其动漂泄沃涌。其德凝惨寒。其变冰雪霜雹。其谷豆稷。其畜彘牛。其果栗枣。其色黑丹。 其味咸苦甘。其象冬。其经足少阴太阳。其藏肾心。其虫鳞。其物濡满。其病胀。上羽而长气不化也。政过则化气大举。而埃昏气交。大雨时降。邪伤肾也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201957,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '25、流衍之纪。是谓封藏。寒司物化。天地严凝。藏政以布。长令不扬。其化凛。其气坚。其政谧。其令流注。其动漂泄沃涌。其德凝惨寒。其变冰雪霜雹。其谷豆稷。其畜彘牛。其果栗枣。其色黑丹。 其味咸苦甘。其象冬。其经足少阴太阳。其藏肾心。其虫鳞。其物濡满。其病胀。上羽而长气不化也。政过则化气大举。而埃昏气交。大雨时降。邪伤肾也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cv1vBbsyCTF', 4, '{"title":"第20201958条・五常政大论篇第七十","description":"<p>26、故曰：不恒其德。则所胜来复。政恒其理。则所胜同化。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201958,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '26、故曰：不恒其德。则所胜来复。政恒其理。则所胜同化。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7H1hoxGNMAT', 4, '{"title":"第20201959条・五常政大论篇第七十","description":"<p>27、帝曰：天不足西北。左寒而右凉。地不满东南。右热而左温。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201959,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '27、帝曰：天不足西北。左寒而右凉。地不满东南。右热而左温。其故何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4AkKw6fFCxT', 4, '{"title":"第20201960条・五常政大论篇第七十","description":"<p>28、岐伯曰：阴阳之气。高下之理。太少之异也。东南方。阳也。阳者其精降于下。故右热而左温。西北方。阴也。阴者其精奉于上。故左寒而右凉。是以地有高下。气有温凉。高者气寒。下者气热。故适寒凉者胀。之温热者疮。下之则胀已。汗之则疮已。此腠理开闭之常。太少之异耳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201960,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '28、岐伯曰：阴阳之气。高下之理。太少之异也。东南方。阳也。阳者其精降于下。故右热而左温。西北方。阴也。阴者其精奉于上。故左寒而右凉。是以地有高下。气有温凉。高者气寒。下者气热。故适寒凉者胀。之温热者疮。下之则胀已。汗之则疮已。此腠理开闭之常。太少之异耳。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mMRhiuHUpPD', 4, '{"title":"第20201961条・五常政大论篇第七十","description":"<p>29、帝 曰：其于寿夭何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201961,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '29、帝 曰：其于寿夭何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nsfx9reKgLR', 4, '{"title":"第20201962条・五常政大论篇第七十","description":"<p>30、岐伯曰：阴精所奉其人寿。阳精所降其人夭。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201962,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '30、岐伯曰：阴精所奉其人寿。阳精所降其人夭。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8DJ5lskXF8o', 4, '{"title":"第20201963条・五常政大论篇第七十","description":"<p>31、帝曰：善。其病也。治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201963,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '31、帝曰：善。其病也。治之奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rjw7UbwE0Bi', 4, '{"title":"第20201964条・五常政大论篇第七十","description":"<p>32、岐伯曰：西北之气散而寒之。东南之气收而温之。所谓同病异治也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201964,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '32、岐伯曰：西北之气散而寒之。东南之气收而温之。所谓同病异治也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RQZExSr6YpV', 4, '{"title":"第20201965条・五常政大论篇第七十","description":"<p>33、故曰：气寒气凉。治以寒凉。行水渍之。气温气热。治以温热。强其内守。必同其气。可使平也。假者反之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201965,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '33、故曰：气寒气凉。治以寒凉。行水渍之。气温气热。治以温热。强其内守。必同其气。可使平也。假者反之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zDq697BTbtK', 4, '{"title":"第20201966条・五常政大论篇第七十","description":"<p>34、帝曰：善。一州之气。生化寿夭不同。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201966,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '34、帝曰：善。一州之气。生化寿夭不同。其故何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sIvU6gLv23z', 4, '{"title":"第20201967条・五常政大论篇第七十","description":"<p>35、岐伯曰：高下之理。地势使然也。崇高则阴气治之。污下则阳气治之。阳胜者先天。阴胜者后天。此地理之常。生化之道也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201967,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '35、岐伯曰：高下之理。地势使然也。崇高则阴气治之。污下则阳气治之。阳胜者先天。阴胜者后天。此地理之常。生化之道也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q8tg8bbMvm4', 4, '{"title":"第20201968条・五常政大论篇第七十","description":"<p>36、帝曰：其有寿夭乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201968,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '36、帝曰：其有寿夭乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fghvNk1HWc9', 4, '{"title":"第20201969条・五常政大论篇第七十","description":"<p>37、岐伯曰：高者其气寿。下者其气夭。地之小大异也。小者小异。大者大异。故治病者。必明天道地理。阴阳更胜。气之先后。人之寿夭。生化之期。乃可以知人之形气矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201969,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '37、岐伯曰：高者其气寿。下者其气夭。地之小大异也。小者小异。大者大异。故治病者。必明天道地理。阴阳更胜。气之先后。人之寿夭。生化之期。乃可以知人之形气矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ILjIxfGFxu0', 4, '{"title":"第20201970条・五常政大论篇第七十","description":"<p>38、帝曰：善。其岁有不病。而藏气不应不用者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201970,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '38、帝曰：善。其岁有不病。而藏气不应不用者何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BXgwcx6e2dR', 4, '{"title":"第20201971条・五常政大论篇第七十","description":"<p>39、岐伯曰：天气制之。气有所从也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201971,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '39、岐伯曰：天气制之。气有所从也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C9Zxy5A5uSc', 4, '{"title":"第20201972条・五常政大论篇第七十","description":"<p>40、帝曰：愿卒闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201972,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '40、帝曰：愿卒闻之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0oqhRRz3byv', 4, '{"title":"第20201973条・五常政大论篇第七十","description":"<p>41、岐伯曰：少阳司天。火气下临。肺气上从。白起金用。草木眚。火见燔焫。革金且耗。大暑以行。咳嚏鼽衄鼻窒。曰疡。寒热肿。风行于地。尘沙飞扬。心痛胃脘痛。厥逆膈不通。其主暴速。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201973,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '41、岐伯曰：少阳司天。火气下临。肺气上从。白起金用。草木眚。火见燔焫。革金且耗。大暑以行。咳嚏鼽衄鼻窒。曰疡。寒热肿。风行于地。尘沙飞扬。心痛胃脘痛。厥逆膈不通。其主暴速。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cSHtFYeDewz', 4, '{"title":"第20201974条・五常政大论篇第七十","description":"<p>42、阳明司天。燥气下临。肝气上从。苍起木用而立。土乃眚。凄沧数至。木伐草萎。胁痛目赤。掉振鼓栗。筋痿不能久立。 暴热至。土乃暑。阳气郁发。小便变。寒热如疟。甚则心痛。火行于稿。流水不冰。蛰虫乃见。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201974,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '42、阳明司天。燥气下临。肝气上从。苍起木用而立。土乃眚。凄沧数至。木伐草萎。胁痛目赤。掉振鼓栗。筋痿不能久立。 暴热至。土乃暑。阳气郁发。小便变。寒热如疟。甚则心痛。火行于稿。流水不冰。蛰虫乃见。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IVnjsCcOy1i', 4, '{"title":"第20201975条・五常政大论篇第七十","description":"<p>43、太阳司天。寒气下临。心气上从。而火且明。丹起金乃眚。寒清时举。胜则水冰。火气高明。心热烦。嗌干善渴。鼽嚏。喜悲数欠。热气妄行。寒乃复。霜不时降。善忘。甚则心痛。土乃润。水丰衍。寒客至。沉阴化。湿气变物。水饮内。中满不食。皮肉苛。筋脉不利。甚则肿身后痈。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201975,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '43、太阳司天。寒气下临。心气上从。而火且明。丹起金乃眚。寒清时举。胜则水冰。火气高明。心热烦。嗌干善渴。鼽嚏。喜悲数欠。热气妄行。寒乃复。霜不时降。善忘。甚则心痛。土乃润。水丰衍。寒客至。沉阴化。湿气变物。水饮内。中满不食。皮肉苛。筋脉不利。甚则肿身后痈。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eio65ntoipD', 4, '{"title":"第20201976条・五常政大论篇第七十","description":"<p>44、厥阴司天。风气下临。脾气上从。而土且隆。黄起水乃眚。土用革。体重肌肉萎。食减口爽。风行太虚。云物摇动。目转耳鸣。火纵其暴。地乃暑。大热消烁。赤沃下。蛰虫数见。流水不冰。其发机速。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201976,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '44、厥阴司天。风气下临。脾气上从。而土且隆。黄起水乃眚。土用革。体重肌肉萎。食减口爽。风行太虚。云物摇动。目转耳鸣。火纵其暴。地乃暑。大热消烁。赤沃下。蛰虫数见。流水不冰。其发机速。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('33G7FHHM1Pq', 4, '{"title":"第20201977条・五常政大论篇第七十","description":"<p>45、少阴司天。热气下临。肺气上从。白起金用。草木眚。喘呕寒热。嚏鼽衄鼻窒。大暑流行。甚则疮疡燔灼。金烁石流。地乃燥清。凄沧数至。胁痛善太息。肃杀行。草木变。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201977,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '45、少阴司天。热气下临。肺气上从。白起金用。草木眚。喘呕寒热。嚏鼽衄鼻窒。大暑流行。甚则疮疡燔灼。金烁石流。地乃燥清。凄沧数至。胁痛善太息。肃杀行。草木变。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z6iWqV2BvkC', 4, '{"title":"第20201978条・五常政大论篇第七十","description":"<p>46、太阴司天。湿气下临。肾气上从。黑起水变。埃冒云雨。胸中不利。阴痿气大衰而不起不用。当其时反腰痛。动转不便也。厥逆。地乃藏阴。大寒且至。蛰虫早附。心下痞痛。地裂冰坚。少腹痛。时害于食。乘金则止水增。味乃咸。行水减也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201978,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '46、太阴司天。湿气下临。肾气上从。黑起水变。埃冒云雨。胸中不利。阴痿气大衰而不起不用。当其时反腰痛。动转不便也。厥逆。地乃藏阴。大寒且至。蛰虫早附。心下痞痛。地裂冰坚。少腹痛。时害于食。乘金则止水增。味乃咸。行水减也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SuYKmoysgqa', 4, '{"title":"第20201979条・五常政大论篇第七十","description":"<p>47、帝曰：岁有胎孕不育。治之不全。何气使然？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201979,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '47、帝曰：岁有胎孕不育。治之不全。何气使然？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
