INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RN5jOUz6Nd7', 4, '{"title":"第20201988条・五常政大论篇第七十","description":"<p>56、故气主有所制。岁立有所生。地气制己胜。天气制胜己。天制色。地制形。五类衰盛。各随其气之所宜也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201988,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '56、故气主有所制。岁立有所生。地气制己胜。天气制胜己。天制色。地制形。五类衰盛。各随其气之所宜也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RcBO7r5hWLC', 4, '{"title":"第20201989条・五常政大论篇第七十","description":"<p>57、故有胎孕不育。治之不全。此气之常也。所谓中根也。根于外者亦五。故生化之别。有五气五味五色五类五宜也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201989,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '57、故有胎孕不育。治之不全。此气之常也。所谓中根也。根于外者亦五。故生化之别。有五气五味五色五类五宜也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WFJyVGUP4V1', 4, '{"title":"第20201990条・五常政大论篇第七十","description":"<p>58、帝曰：何谓也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201990,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '58、帝曰：何谓也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NNb9p0H15Hd', 4, '{"title":"第20201991条・五常政大论篇第七十","description":"<p>59、岐伯曰：根于中者。命曰神机。神去则机息。根于外者。命曰气立。气止则化绝。故各有制。各有胜。各有生。各有成。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201991,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '59、岐伯曰：根于中者。命曰神机。神去则机息。根于外者。命曰气立。气止则化绝。故各有制。各有胜。各有生。各有成。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h5HKs1ltzJs', 4, '{"title":"第20201992条・五常政大论篇第七十","description":"<p>60、故曰：不知年之所加。气之同异。不足以言生化。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201992,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '60、故曰：不知年之所加。气之同异。不足以言生化。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H5y4RI0W9kD', 4, '{"title":"第20201993条・五常政大论篇第七十","description":"<p>61、帝曰：气始而生化。气散而有形。气布而蕃育。气终而象变。其致一也。然而五味所资。生化有薄浓。成熟有少多。终始不同。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201993,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '61、帝曰：气始而生化。气散而有形。气布而蕃育。气终而象变。其致一也。然而五味所资。生化有薄浓。成熟有少多。终始不同。其故何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5moWTohEx81', 4, '{"title":"第20201994条・五常政大论篇第七十","description":"<p>62、岐伯曰：地气制之也。非天不生。地不长也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201994,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '62、岐伯曰：地气制之也。非天不生。地不长也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l2yzdNAgrGu', 4, '{"title":"第20201995条・五常政大论篇第七十","description":"<p>63、帝曰：愿闻其道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201995,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '63、帝曰：愿闻其道。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
