INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4RweZJ66lVD', 4, '{"title":"第20202000条・五常政大论篇第七十","description":"<p>68、厥阴在泉。清毒不生。其味甘。其治酸苦。其谷苍赤。其气专。其味正。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '68、厥阴在泉。清毒不生。其味甘。其治酸苦。其谷苍赤。其气专。其味正。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FSRE7JqPvE7', 4, '{"title":"第20202001条・五常政大论篇第七十","description":"<p>69、少阴在泉。寒毒不生。其味辛。其治辛苦甘。其谷白丹。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '69、少阴在泉。寒毒不生。其味辛。其治辛苦甘。其谷白丹。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dm743AY0qvY', 4, '{"title":"第20202002条・五常政大论篇第七十","description":"<p>70、太阴在泉。燥毒不生。其味咸。其气热。其治甘咸。其谷黅秬。化淳则咸守。气专则辛化而俱治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '70、太阴在泉。燥毒不生。其味咸。其气热。其治甘咸。其谷黅秬。化淳则咸守。气专则辛化而俱治。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yt0pmtkObJq', 4, '{"title":"第20202003条・五常政大论篇第七十","description":"<p>71、故曰：补上下者从之。治上下者逆之。以所在寒热盛衰而调之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '71、故曰：补上下者从之。治上下者逆之。以所在寒热盛衰而调之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OTRQktbayoT', 4, '{"title":"第20202004条・五常政大论篇第七十","description":"<p>72、故曰：上取下取。内取外取。以求其过。能毒者以浓药。不胜毒者以薄药。 此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '72、故曰：上取下取。内取外取。以求其过。能毒者以浓药。不胜毒者以薄药。 此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gi0S1oTh1E9', 4, '{"title":"第20202005条・五常政大论篇第七十","description":"<p>73、气反者。病在上。取之下。病在下。取之上。病在中。旁取之。治热以寒。温而行之。治寒以热。凉而行之。治温以清。冷而行之。治清以温。热而行之。故消之削之。吐之下之。补之泻之。久新同法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '73、气反者。病在上。取之下。病在下。取之上。病在中。旁取之。治热以寒。温而行之。治寒以热。凉而行之。治温以清。冷而行之。治清以温。热而行之。故消之削之。吐之下之。补之泻之。久新同法。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HSF7w3193Hg', 4, '{"title":"第20202006条・五常政大论篇第七十","description":"<p>74、帝曰： 病在中而不实不坚。且聚且散。奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '74、帝曰： 病在中而不实不坚。且聚且散。奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('40kwYdpfJ3m', 4, '{"title":"第20202007条・五常政大论篇第七十","description":"<p>75、岐伯曰：悉乎哉问也！无积者求其藏。虚则补之。药以祛之。食以随之。行水渍之。和其中外。可使毕已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '75、岐伯曰：悉乎哉问也！无积者求其藏。虚则补之。药以祛之。食以随之。行水渍之。和其中外。可使毕已。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7CvbrSzj82s', 4, '{"title":"第20202008条・五常政大论篇第七十","description":"<p>76、帝曰：有毒无毒。服有约乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '76、帝曰：有毒无毒。服有约乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('19eQ5BLW2ku', 4, '{"title":"第20202009条・五常政大论篇第七十","description":"<p>77、岐伯曰：病有久新。方有大小。有毒无毒。固宜常制矣。大毒治病。十去其六。常毒治病。十去其七。小毒治病。十去其八。无毒治病。十去其九。谷肉果菜。食养尽之。无使过之。伤其正也。不尽。行复如法。必先岁气。无伐天和。无盛盛。无虚虚。而遗人天殃。无致邪。无失正。绝人长命。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '77、岐伯曰：病有久新。方有大小。有毒无毒。固宜常制矣。大毒治病。十去其六。常毒治病。十去其七。小毒治病。十去其八。无毒治病。十去其九。谷肉果菜。食养尽之。无使过之。伤其正也。不尽。行复如法。必先岁气。无伐天和。无盛盛。无虚虚。而遗人天殃。无致邪。无失正。绝人长命。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('asBABmLYvO1', 4, '{"title":"第20202010条・五常政大论篇第七十","description":"<p>78、帝曰：其久病者。有气从不康。病去而瘠。奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '78、帝曰：其久病者。有气从不康。病去而瘠。奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LJ5YPHMW3eP', 4, '{"title":"第20202011条・五常政大论篇第七十","description":"<p>79、岐伯曰：昭乎哉圣人之问也！化不可代。时不可违。夫经络以通。血气以从。复其不足。与众齐同。养之和之。静以待时。谨守其气。无使倾移。其形乃彰。生气以长。命曰圣王。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '79、岐伯曰：昭乎哉圣人之问也！化不可代。时不可违。夫经络以通。血气以从。复其不足。与众齐同。养之和之。静以待时。谨守其气。无使倾移。其形乃彰。生气以长。命曰圣王。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MQZmO7McNWF', 4, '{"title":"第20202012条・五常政大论篇第七十","description":"<p>80、故大要曰：无代化。无违时。必养必和。待其来复。此之谓也。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '80、故大要曰：无代化。无违时。必养必和。待其来复。此之谓也。帝曰：善。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'm6A2KjZBg5n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DgnfpammhCE', 4, '{"title":"第20202013条・六元正纪大论篇第七十一","description":"<p>1、黄帝问曰：六化六变。胜复淫治。甘苦辛咸酸淡先后。余知之矣。夫五运之化。或从五气。或逆天气。或从天气而逆地气。或从地气而逆天气。或相得。或不相得。余未能明其事。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '1、黄帝问曰：六化六变。胜复淫治。甘苦辛咸酸淡先后。余知之矣。夫五运之化。或从五气。或逆天气。或从天气而逆地气。或从地气而逆天气。或相得。或不相得。余未能明其事。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8rohEWX4ELi', 4, '{"title":"第20202014条・六元正纪大论篇第七十一","description":"<p>2、欲通天之纪。从地之理。和其运。调其化。使上下合德。无相夺伦。天地升降。不失其宜。五运宣行。勿乖其政。调之正味。从逆奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2、欲通天之纪。从地之理。和其运。调其化。使上下合德。无相夺伦。天地升降。不失其宜。五运宣行。勿乖其政。调之正味。从逆奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kuhnucVn8Zi', 4, '{"title":"第20202015条・六元正纪大论篇第七十一","description":"<p>3、岐伯稽首再拜对曰：昭乎哉问也。此天地之纲纪。变化之渊源。非圣帝孰能穷其至理欤！臣虽不敏。请陈其道。令终不灭。久而不易。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '3、岐伯稽首再拜对曰：昭乎哉问也。此天地之纲纪。变化之渊源。非圣帝孰能穷其至理欤！臣虽不敏。请陈其道。令终不灭。久而不易。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('brmH1XXtv3I', 4, '{"title":"第20202016条・六元正纪大论篇第七十一","description":"<p>4、帝曰：愿夫子推而次之。从其类序。分其部主。别其宗司。昭其气数。明其正化。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '4、帝曰：愿夫子推而次之。从其类序。分其部主。别其宗司。昭其气数。明其正化。可得闻乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0CRZgund5NL', 4, '{"title":"第20202017条・六元正纪大论篇第七十一","description":"<p>5、岐伯曰：先立其年以明其气。金木水火土营运之数。寒暑燥湿风火临御之化。则天道可见。民气可调。阴阳卷舒。近而无惑。数之可数者。请遂言之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '5、岐伯曰：先立其年以明其气。金木水火土营运之数。寒暑燥湿风火临御之化。则天道可见。民气可调。阴阳卷舒。近而无惑。数之可数者。请遂言之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
